import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
    selector: 'app-footer',
    standalone: true,
    imports: [CommonModule],
    template: `
    <footer class="footer">
      <div class="container footer-content">
        <div class="footer-logo">ZO.</div>
        <p class="copyright">© 2026 Zakariae OUKHAMOU. All Rights Reserved.</p>
        <div class="footer-links">
          <a href="#">Privacy</a>
          <a href="#">Terms</a>
        </div>
      </div>
    </footer>
  `,
    styles: [`
    .footer {
      background-color: var(--bg-color);
      border-top: 1px solid rgba(0,0,0,0.1);
      padding: 2rem 0;
      margin-top: auto;
    }

    .footer-content {
      display: flex;
      justify-content: space-between;
      align-items: center;

      @media(max-width: 768px) {
        flex-direction: column;
        gap: 1rem;
      }
    }

    .footer-logo {
      font-weight: 700;
      font-size: 1.5rem;
      color: var(--primary-color);
    }

    .copyright {
      font-size: 0.9rem;
      color: var(--text-color);
      opacity: 0.6;
    }

    .footer-links {
      display: flex;
      gap: 1.5rem;
      
      a {
        text-decoration: none;
        color: var(--text-color);
        opacity: 0.6;
        font-size: 0.9rem;
        &:hover { opacity: 1; color: var(--primary-color); }
      }
    }
  `]
})
export class FooterComponent { }
